CREATE OR REPLACE FUNCTION public.admin_set_pool(p_actor text, p_set text, p_cards bigint[], p_add boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
